b:if.b:template-skin:
/* ── Layout editor (Bố cục) — CÔNG CỤ.AI pro board ── */
body#layout{
  background:
    radial-gradient(circle at 12% 0%, rgba(212,175,55,.08), transparent 34%),
    linear-gradient(180deg,#070b08 0%,#0a100d 100%)!important;
  border:1px solid #243328!important;
  color:#e8fff2!important;
  font-family:'Space Grotesk',Arial,sans-serif!important;
  padding:18px!important;
  box-sizing:border-box!important;
}
body#layout::before{
  content:'CÔNG CỤ.AI  ·  Bố cục theme';
  display:block;
  margin:0 0 14px;
  padding:10px 14px;
  border:1px solid rgba(212,175,55,.35);
  border-radius:12px;
  background:rgba(8,14,10,.92);
  color:#f3e2a8;
  font:700 13px/1.3 monospace;
  letter-spacing:.08em;
  text-transform:uppercase;
}
body#layout .qcx-signal-header,
body#layout .qcx-mac-topbar,
body#layout .qcx-site-footer,
body#layout .qcx-mobile-cta,
body#layout .qcx-scanline,
body#layout .qcx-backdrop,
body#layout .footer-navigation-bar,
body#layout #qcx-menu,
body#layout #qcx-menu-backdrop,
body#layout #qcx-mobile-search,
body#layout #qcx-native-tabbar{display:none!important}
body#layout header,
body#layout .main-container{display:block!important;width:100%!important;max-width:none!important;float:none!important;padding:0!important;margin:0!important}
/* Layout editor: float main left + Thanh bên right (Blogger strips grid-template-columns here). */
body#layout .main-wrapper{
  display:block!important;
  width:100%!important;
  max-width:none!important;
  float:none!important;
  padding:0!important;
  margin:0 0 14px!important;
  box-sizing:border-box!important;
  overflow:hidden!important;
}
body#layout #brand,
body#layout #header,
body#layout #menu,
body#layout #homepage-widgets,
body#layout #main,
body#layout #below-main,
body#layout #sidebar,
body#layout #footer{
  display:block!important;
  float:none!important;
  clear:both!important;
  width:100%!important;
  min-height:92px!important;
  margin:0 0 14px!important;
  padding:14px!important;
  box-sizing:border-box!important;
  border:1px solid rgba(28,36,32,.18)!important;
  border-radius:14px!important;
  background:rgba(10,18,13,.96)!important;
  box-shadow:0 10px 28px rgba(0,0,0,.28)!important;
  position:relative!important;
}
body#layout #brand{border-color:rgba(212,175,55,.4)!important;background:linear-gradient(135deg,rgba(20,16,8,.98),rgba(8,12,9,.98))!important}
body#layout #header,body#layout #menu{width:calc(50% - 8px)!important;display:inline-block!important;vertical-align:top!important;clear:none!important}
body#layout #menu{margin-left:16px!important}
body#layout #main{
  float:left!important;
  clear:none!important;
  /* content-box in layout iframe: leave headroom for padding/border */
  width:60%!important;
  max-width:60%!important;
  min-height:220px!important;
  margin:0!important;
  padding:10px!important;
  border-color:rgba(28,36,32,.35)!important;
}
body#layout #sidebar{
  float:right!important;
  clear:none!important;
  width:35%!important;
  max-width:35%!important;
  min-height:220px!important;
  margin:0!important;
  padding:10px!important;
  border-color:rgba(212,175,55,.45)!important;
}
body#layout #below-main{
  float:none!important;
  clear:both!important;
  width:100%!important;
  margin:14px 0 0!important;
}
body#layout .main-wrapper::after{
  content:''!important;
  display:table!important;
  clear:both!important;
}
body#layout .widget{
  position:static!important;
  opacity:1!important;
  visibility:visible!important;
  margin:8px 0!important;
  padding:12px!important;
  border:1px solid rgba(255,255,255,.08)!important;
  border-radius:10px!important;
  background:rgba(255,255,255,.03)!important;
  color:#e8fff2!important;
}
body#layout .widget > h2,
body#layout .widget .title{color:#20d99a!important;font:700 12px/1.3 monospace!important;margin:0 0 8px!important}
body#layout .qcx-layout-brand{
  display:flex!important;
  align-items:center!important;
  gap:14px!important;
}
body#layout .qcx-layout-brand img{
  width:72px!important;height:72px!important;border-radius:16px!important;
  border:1px solid rgba(212,175,55,.45)!important;object-fit:cover!important;background:#000!important;
}
body#layout .qcx-layout-brand strong{display:block;color:#fff;font-size:18px;letter-spacing:.04em}
body#layout .qcx-layout-brand span{display:block;color:rgba(230,245,236,.7);font-size:12px;margin-top:4px}

