/*  */
/* SFProDisplay / vietblogdao CDN removed for supply-chain + performance. UI uses JetBrains Mono. */
html{color-scheme:dark}
body,input,button,textarea,pre{font-family:'JetBrains Mono',ui-monospace,Menlo,Consolas,monospace;font-display:swap}
  /*  */

/*  */
article,aside,details,figcaption,figure,footer,header,hgroup,menu,nav,section{display:block}
a,abbr,acronym,address,applet,big,blockquote,body,caption,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,figure,font,form,h1,h2,h3,h4,h5,h6,html,iframe,img,ins,kbd,label,legend,li,object,ol,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,ul,var{margin:0;padding:0}
ol,ol ol,ul,ul ul{padding:0}a,a:hover{text-decoration:none}[data-view-type=mobile] a:hover{cursor:default;outline:none}[data-view-type=mobile] a:focus{outline:none}[data-view-type=desktop] .has-hover:hover,[data-view-type=desktop] [data-hover]:hover{cursor:pointer}
table{border-collapse:separate;border-spacing:0}caption,td,th{text-align:left;font-weight:400}
a img{border:none}img.lazyload{width:100%}iframe{width: 100%;border:0}ins{text-decoration:none}
img{-webkit-animation:fadeInImages 0.5s ease;animation:fadeInImages 0.5s ease}.align-middle{vertical-align:middle;max-width:100%;height:auto}
body,input,button,textarea,pre{font-family:'JetBrains Mono',ui-monospace,Menlo,Consolas,monospace;font-size:1rem;-webkit-tap-highlight-color:rgba(0,0,0,0)}
*{box-sizing:border-box;-moz-box-sizing:border-box;-ms-box-sizing:border-box;text-rendering:geometricPrecision}
body{background:#f8f9fa;color:rgba(0,0,0,0.87);min-height:100vh;overflow:hidden;overflow-y:auto}
svg{vertical-align:text-bottom;fill:hsl(0,0%,53.3%)}
.flex{display:-ms-flexbox;display:-webkit-flex;display:flex}.flex-align{display:-webkit-flex;display:-ms-flexbox;display:flex;-webkit-align-items:center;-ms-flex-align:center;align-items:center}.flex-center{display:-webkit-flex;display:-ms-flexbox;display:flex;-webkit-align-items:center;-ms-flex-align:center;align-items:center;justify-content:center}.flex-right{margin-left:auto}.flex-left{margin-right:auto}.text-center{text-align:center}
.align-center{-webkit-align-items:center;align-items:center}
.lazyload,.lazyloading{opacity:0}.lazyloaded{opacity:1;transition:opacity 300ms}
.overlay{background:rgba(0,0,0,0.502);position:fixed;top:0;bottom:0;left:0;right:0;z-index:15;transition:opacity .05s cubic-bezier(0.4,0.0,0.2,1);opacity:1}
.overlay.hidden{opacity:0;transition:opacity .15s cubic-bezier(0.4,0.0,0.2,1) .15s}
.hidden,span.blog-admin,.img-first-child,.button.loading svg,.preload .blog-posts,.footer .widget.script,[data-allow-comments="false"] a.comment-reply{display:none}
.fb_iframe_widget_fluid_desktop iframe[style]{width:100%!important}
