    var url=window.location.href,uri=window.location.toString(),
    rel=document.querySelector('link[rel="canonical"]').getAttribute('href'),
    beforeParam=function(value,param){var index=value.indexOf(param);return index===-1?value:value.substring(0,index)},
    fb1=beforeParam(url,'?fbclid'),fb2=beforeParam(url,'&fbclid'),
    gi1=beforeParam(url,'?gidzl'),gi2=beforeParam(url,'&gidzl'),
    m1=beforeParam(url,'?m=1'),m2=beforeParam(url,'&m=1')
    if((uri.length-fb1.length)>0)window.history.replaceState({},document.title,fb1)
    if((uri.length-fb2.length)>0)window.history.replaceState({},document.title,fb2)
    if((uri.length-gi1.length)>0)window.history.replaceState({},document.title,gi1)
    if((uri.length-gi2.length)>0)window.history.replaceState({},document.title,gi2)
    function appendChildHead(name,type){
      if(type=='css'){
        var fileref=document.createElement('link')
        fileref.setAttribute('rel','stylesheet')
        fileref.setAttribute('href',name)
      }else if(type=='js'){
        var fileref=document.createElement('script')
        fileref.setAttribute('type','text/javascript')
        fileref.setAttribute('async','')
        fileref.setAttribute('src',name)
      }
      if(typeof fileref!='undefined'){document.getElementsByTagName('head')[0].appendChild(fileref)}
    }
    window.addEventListener('load',function(){
      if(navigator.userAgent.match(/(iPhone|iPod|iPad|Android|BlackBerry|Windows Phone|webOS)/i)===null
      ||window.navigator.pointerEnabled&&navigator.maxTouchPoints>1){
        document.documentElement.setAttribute('data-view-type','desktop')
        if((uri.length-m1.length)>0){window.history.replaceState({},document.title,m1)}
        if((uri.length-m2.length)>0){window.history.replaceState({},document.title,m2)}
        var _a=document.querySelectorAll('a')
        for(var i=0;i<_a.length;i++){
          var _b=_a[i].getAttribute('href')
          if(_b!=null){
            if(_b.indexOf('?m=1')!=-1)_a[i].setAttribute('href',_b.substr(0,_b.indexOf('?m=1')))
            if(_b.indexOf('&m=1')!=-1)_a[i].setAttribute('href',_b.substr(0,_b.indexOf('&m=1')))
          }
        }
      }else{document.documentElement.setAttribute('data-view-type','mobile')}
      if(data.view.isPost!='true'){
        var item=document.querySelectorAll('.menu li>a')
        for(var i=0;i<item.length;i++){
          var y=item[i].getAttribute('href')
          if(y.indexOf('?')!=-1) y=y.substr(0,y.indexOf('?'))
          if(rel==y)item[i].parentElement.classList.add('current')
        }
      }
      if(data.view.isMobile!='true'){
        var scrollTop=document.querySelector('.scroll--top')
        if(scrollTop){
          var syncScrollTop=function(){
            if(window.scrollY<=0)scrollTop.classList.remove('show')
            else scrollTop.classList.add('show')
          }
          syncScrollTop()
          window.addEventListener('scroll',syncScrollTop,{passive:true})
          scrollTop.addEventListener('click',function(e){
            e.preventDefault()
            window.scrollTo({top:0,behavior:'smooth'})
          })
        }
      }
      const header=document.querySelector('header'),menu=document.querySelector('.menu'),
        title=document.querySelectorAll('.menu .title:not(.home)'),button=document.querySelector('.header button.open'),
        input=document.querySelector('.web-search input'),results=document.querySelector('.web-search .results-content'),
        li=document.querySelectorAll('.results-content li'),reset=document.querySelector('.web-search .reset'),
        search=document.querySelectorAll('.web-search,.web-search .results-content'),
        overlay=document.querySelector('.overlay'),elems=document.querySelectorAll('header,.overlay'),
        close=document.querySelectorAll('.menu .home,.overlay'),nabar=document.querySelector('.footer-navigation-bar'),
        buttons=document.querySelector('.footer-navigation-bar .open-menu'),
        searchs=document.querySelector('.footer-navigation-bar .open-search')
      if(window.matchMedia('(max-width:860px)').matches){for(var i=0;i<title.length;i++)title[i].classList.add('has-sub')}
      window.addEventListener('resize',function(){
        if(this.matchMedia('(max-width:860px)').matches){
          for(var i=0;i<title.length;i++){
            title[i].classList.add('has-sub')
            title[i].addEventListener('click',function(){this.classList.toggle('has-toggle')})
          }
        }else{
          if(!menu.classList.contains('section'))menu.classList.add('section')
          if(!overlay.classList.contains('hidden'))overlay.classList.add('hidden')
          for(var i=0;i<title.length;i++)title[i].classList.remove('has-sub')
        }
      })
      for(var i=0;i<title.length;i++){
        if(title[i].classList.contains('has-sub')){title[i].addEventListener('click',function(){this.classList.toggle('has-toggle')})}
      }
      button.addEventListener('click',function(e){
        e.stopPropagation()
        button.setAttribute('aria-expanded','true')
        button.setAttribute('aria-pressed','true')
        overlay.classList.remove('hidden')
        menu.classList.remove('section')
        if(!results.classList.contains('hidden'))results.classList.add('hidden')
        if(header.hasAttribute('has-fixed'))header.removeAttribute('has-fixed')
      })
      for(var i=0;i<close.length;i++){
        close[i].addEventListener('click',function(){
          button.setAttribute('aria-expanded','false')
          button.setAttribute('aria-pressed','false')
          overlay.classList.add('hidden')
          menu.classList.add('section')
        })
      }
      menu.addEventListener('click',function(e){e.stopPropagation()})
      input.addEventListener('click',function(e){
        e.stopPropagation()
        header.setAttribute('has-fixed','')
        overlay.classList.remove('hidden')
        results.classList.remove('hidden')
        if(!menu.classList.contains('section'))menu.classList.add('section')
      })
      for(var i=0;i<search.length;i++){
        search[i].addEventListener('click',function(e){
          e.stopPropagation()
        })
      }
      for(var i=0;i<elems.length;i++){
        elems[i].addEventListener('click',function(){
          overlay.classList.add('hidden')
          results.classList.add('hidden')
          header.removeAttribute('has-fixed')
        })
      }
      buttons.addEventListener('click',function(e){
        e.stopPropagation()
        overlay.classList.remove('hidden')
        menu.classList.remove('section')
        if(!results.classList.contains('hidden'))results.classList.add('hidden')
        if(header.hasAttribute('has-fixed'))header.removeAttribute('has-fixed')
      })
      searchs.addEventListener('click',function(e){
        e.stopPropagation()
        input.focus()
        header.setAttribute('has-fixed','')
        overlay.classList.remove('hidden')
        results.classList.remove('hidden')
        if(!menu.classList.contains('section'))menu.classList.add('section')
      })
      if(data.view.isPost=='true'){
        const share_button=document.querySelector('.footer-navigation-bar .share-post'),
        share_menu=document.querySelector('.footer-navigation-bar .share-menu'),
        close_menu=document.querySelector('.footer-navigation-bar .share-menu>li:first-child>span>svg'),
        sroll_comments=document.querySelector('.footer-navigation-bar .sroll-comments')
        share_button.addEventListener('click',function(e){
          e.preventDefault()
          share_menu.classList.remove('visible')
        })
        close_menu.addEventListener('click',function(e){
          e.preventDefault()
          share_menu.classList.add('visible')
        })
        sroll_comments.addEventListener('click',function(e){
          e.preventDefault()
          document.getElementById('comments').scrollIntoView({behavior:'smooth'})
        })
      }
      if(data.view.isPost!='true'){  
        const sroll_top=document.querySelector('.footer-navigation-bar .scroll-top')
        if (sroll_top) {
          sroll_top.addEventListener('click',function(){window.scrollTo({top:0,behavior:'smooth'})})
        }
      }
      var typingTimer
      function _reset(){
        for(var i=0;i<li.length;i++){
         li[i].innerHTML=li[i].textContent
         li[i].removeAttribute('class')
        }
      }
      input.addEventListener('keyup',function(){
        clearTimeout(typingTimer)
        var val=this.value
        setTimeout(function(){results.classList.remove('hidden')},100)
        reset.classList.remove('hidden')
        if(val!=''){
          typingTimer=setTimeout(function(){
            var str=val.toLowerCase(),name='',stn=''
            for(var i=0;i<li.length;i++){            
              stn=li[i].textContent
              name=stn.toLowerCase()
              var res=name.indexOf(str),
              reg=name.slice(res,Number(res)+str.length)
              if(res!=-1){
                li[i].removeAttribute('class')
                li[i].innerHTML=name.replace(reg,'<strong>'+reg+'</strong>')         
              }else{li[i].classList.add('hidden')}
            }
          },500)
        }else{_reset()}
        reset.addEventListener('click',function(e){
          e.stopPropagation()
          reset.classList.add('hidden')
          _reset()
        })
      })
      for(var i=0;i<li.length;i++){
        li[i].addEventListener('click',function(){
          if(data.view.isMobile!='true')location.href='/search/label/'+this.getAttribute('data-search')
          else location.href='/search/label/'+this.getAttribute('data-search')+'?m=1'
        })
      }
    })
