    window.addEventListener('load',function(){
      var a='.all_posts>.row',b='.col-md-4',c='.blog-pager>a',
      d=document.querySelector(c)
      if(!d)return
      var e=d.getAttribute('href')||''
      function state(label,className){
        d.textContent=label
        d.classList.remove('is-loading','is-error')
