        d.removeAttribute('aria-busy')
      }
      function f(){setTimeout(function(){
        state('Đã tải hết','disabled')
        d.setAttribute('aria-disabled','true')
        d.removeAttribute('href')
      },350)}
      function m(){setTimeout(function(){state(data.messages.loadMore,'')},250)}
      function x(){setTimeout(function(){state('Thử lại','is-error')},250)}
      function n(v){
        v.preventDefault()
        if(d.classList.contains('disabled')||d.classList.contains('is-loading'))return
        state(data.messages.loading,'is-loading')
        d.setAttribute('aria-busy','true')
        if(e!=''){
          $.get(e,function(g){
            var h=$(g).find(b)
            if(h.length){
              var i=document.createElement('div'),j=$(i).append(g),k=j.find(c)
              if(k.length)(e=k.attr('href'),d.setAttribute('href',e))
              else e=''
              var l=j.find(a).children(b)
              $(a).append(l)
              m()
            }else f()              
          },'html').fail(x)
        }else f()
      }
      d.addEventListener('click',n)
    })
