      window.addEventListener('load',function(){
        var target='#'+$('.modal--target').attr('id'),
        canonical=$('link[rel="canonical"]').attr('href')
        $('.modal--open').on('click',function(e){
          e.preventDefault()
          $('.header').addClass('visible')
