        e.preventDefault()
        var id=$(this).attr('href')
        id=id.substr(id.indexOf('#')+1)
        $('html,body').animate({scrollTop:$('h3[id='+id+']').offset().top-$('body>header').height()},1000)
      })      
      for(var k=0;k<th.length;k++){
        th[k].addEventListener('click',function(){
          $('html,body').animate({scrollTop:$('.box_tin.category').offset().top-$('body>header').height()},1000)
        })
      }
      function copyLinkToClipboard(e){
        var t=document.createElement('textarea')
        t.value=e,document.body.appendChild(t),t.select()
        try{document.execCommand('copy')
        }catch(o){alert("!!!")}
        document.body.removeChild(t)
      }
      $('.copy').click(function(){
        copyLinkToClipboard(data.blog.url)
        $('body').append('<div class="modals"><div class="modals-dialog"><div class="modals-dialog-content flex-align">'+ data.messages.linkCopiedToClipboard +' <svg class="modals-dialog-buttons" height="21px" width="21px" viewBox="0 0 24 24"><path fill="currentColor" d="M19,6.41L17.59,5L12,10.59L6.41,5L5,6.41L10.59,12L5,17.59L6.41,19L12,13.41L17.59,19L19,17.59L13.41,12L19,6.41Z"></path></svg></div></div></div>')
        setTimeout(function(){$('.modals').remove()},4000)
        $('.modals-dialog-buttons').click(function(){$(this).parents('.modals').remove()})
      }) 
      $('.social-wrapper').click(function(e){e.preventDefault()})
      var a=document.getElementsByClassName('social-wrapper'),o=a.length
      for(i=0;i<o;i++) a[i].addEventListener('click',function(t,e,a){
        t=this.getAttribute('data-href')
        var o=screen.width/2-200,n=screen.height/2-225;
        window.open(t,"popUpWindow","height=450,width=400,left="+o+",top="+n+ ",resizable=yes,scrollbars=yes,toolbar=yes,menubar=no,location=no,directories=no,status=yes")
      })
      $('.keywords .more-icon').click(function(){$(this).parent().toggleClass('expanded')})
      $('.menu li>a').each(function(){
        var x=$('.post-label a').attr('href'),y=$(this).attr('href')
        if(x==y)$(this).parent().addClass('current')
      })       
    })
	//

//
      window.addEventListener('load',function(){
        var pre=document.querySelectorAll('.post-body>pre')
        $(pre).each(function(i){
          $(this).append('<button aria-label="Copy" data-label="Click To Copy" data-hover="" data-title="Copy"><svg width="24px" height="24px" viewBox="0 0 24 24"><path fill="#707070" d="M19,21H8V7H19M19,5H8A2,2 0 0,0 6,7V21A2,2 0 0,0 8,23H19A2,2 0 0,0 21,21V7A2,2 0 0,0 19,5M16,1H4A2,2 0 0,0 2,3V17H4V3H16V1Z"/></svg></button>')
          var button=$(this).find('button')
          $(button).on('click',function(event){
            if(window.getSelection&&document.createRange){
              var range=document.createRange()
              range.selectNodeContents(pre[i])
              var sel=window.getSelection()
              sel.removeAllRanges()
              sel.addRange(range)
            }else if(document.body.createTextRange){
              var textRange=document.body.createTextRange()
              textRange.moveToElementText(pre[i])
              textRange.select()
            }
            try{var successful=document.execCommand('copy'),msg=successful?'successful':'unsuccessful'
            }catch(err){console.log('Oops,unable to copy')}
            $('body').append('<div class="modals"><div class="modals-dialog"><div class="modals-dialog-content flex-align">Đã sao chép vào khay nhớ tạm!<svg class="modals-dialog-buttons has-hover" height="21px" width="21px" viewBox="0 0 24 24"><path fill="currentColor" d="M19,6.41L17.59,5L12,10.59L6.41,5L5,6.41L10.59,12L5,17.59L6.41,19L12,13.41L17.59,19L19,17.59L13.41,12L19,6.41Z"></path></svg></div></div></div>')
            setTimeout(function(){$('.modals').remove()},3000)
            $('.modals-dialog-buttons').click(function(){$(this).parents('.modals').remove()})
          })
        })
      })
	//

//
    window.addEventListener('load',function(){
      var _a=document.querySelectorAll('.post-body a[href^="https:"]')
      for(var i=0;i<_a.length;i++){
        var _b=_a[i].getAttribute('href')
        if(_b!=null){
          if(_b.indexOf(data.blog.homepageUrl)!=-1){
           if(_b.indexOf('?')!=-1)_a[i].setAttribute('href',_b+'&m=1')
           else _a[i].setAttribute('href',_b+'?m=1')
          }
        }
      }
    })
    //

//
      window.addEventListener('load',function(){
        var url = String(location.href || '')
        var elem = document.querySelector('#comments .commentForm') || document.querySelector('.commentForm')
        function qcxLoadCommentIframe(){
          if(!elem || elem.getAttribute('data-qcx-cmt-loaded')==='1') return
          if(!document.getElementById('comment-editor-src')) return
          if(typeof data === 'undefined' || !data.blog || !data.blog.blogId) return
          elem.setAttribute('data-qcx-cmt-loaded','1')
          if($('#comments').hasClass('threaded')){appendChildHead('https://www.blogger.com/dyn-css/authorization.css?targetBlogID='+data.blog.blogId,'css')}
          $(elem).removeClass('hidden')
          if(!document.getElementById('comment-editor')){
            $(elem).append('<iframe class="blogger-iframe-colorize blogger-comment-from-post" id="comment-editor" name="comment-editor" src="" title="comment iframe"></iframe>')
          }
          $.getScript('https://www.blogger.com/static/v1/jsbin/2567313873-comment_from_post_iframe.js').done(function(){
            try { BLOG_CMT_createIframe('https://www.blogger.com/rpc_relay.html') } catch(e) {}
            $(elem).removeClass('spinner')
          })
        }
        if($('#comments').length){
          qcxLoadCommentIframe()
          $('.post-header a.post-comment').click(function(){ if(elem) elem.scrollIntoView({behavior:'smooth'}) })
          $('.comment a.comment-reply').click(function(){
            var l=$('#comment-editor').attr('src') || ''
            $('.calcel-reply').remove()
            $('.comment-actions').removeAttr('style')
            var $this=$(this)
            var id=$this.attr('data-comment-id')
            l=l+'&parentID='+id
            var li=$this.parent().parent().parent().attr('id')
            $('#comment-editor').attr('src',l)
            $this.parent().hide()
            $(elem).appendTo($('#'+li+'>.comment-replybox-single'))
            elem.scrollIntoView({behavior:'smooth'})
            $('#'+li+'>.comment-replybox-single').append('<div class="calcel-reply"><button class="theme-button blue has-hover" type="button">Hủy</button></div>')
            $('.calcel-reply').click(function(){
              $(this).remove()
              $('.comment-actions').removeAttr('style')
              $(elem).appendTo($('#comments .comment-form'))
              elem.scrollIntoView({behavior:'smooth'})
            })
          })
          if(url.indexOf('#comments')!=-1 && elem){elem.scrollIntoView({behavior:'smooth'})}
        }
      })
	//

//
      window.addEventListener('load',function(){
        var load_analytic=0
        function _analytics(){
          if(load_analytic==0){
            load_analytic=1
            appendChildHead('https://www.googletagmanager.com/gtag/js?id='+data.blog.analyticsAccountNumber,'js')
            window.dataLayer=window.dataLayer||[]
            function gtag(){dataLayer.push(arguments)}
            gtag('js', new Date())
            gtag('config',data.blog.analyticsAccountNumber)
          }
        }
        window.addEventListener('scroll',function(){_analytics()})
        window.addEventListener('mousemove',function(){_analytics()})
        setTimeout(function(){_analytics()},3000)
      })
    //

