body.script:
//
function qcxBootMacFrames() {
  // --- MacOS Frame for Images, Videos, Code (all post media) ---
  var body = document.querySelector('.post-body');
  if (!body) return;
  var elementsToWrap = body.querySelectorAll('img, video, pre');
  elementsToWrap.forEach(function(el) {
    var targetNode = el;

    if (el.tagName === 'IMG') {
      /* Skip tiny icons / tracking pixels. */
      var nw = el.naturalWidth || parseInt(el.getAttribute('width'), 10) || 0;
      var nh = el.naturalHeight || parseInt(el.getAttribute('height'), 10) || 0;
      var cw = el.clientWidth || 0;
      if ((nw && nw < 64) || (nh && nh < 64) || (cw && cw < 48)) return;
      if (el.closest('.qcx-sidebar-rail, #sidebar, .emoji, .smiley')) return;

      if (el.parentNode && el.parentNode.tagName === 'A') targetNode = el.parentNode;
      if (
        targetNode.parentNode &&
        targetNode.parentNode.classList &&
        targetNode.parentNode.classList.contains('separator')
      ) {
        targetNode = targetNode.parentNode;
      }
    }

    if (!targetNode || !targetNode.parentNode) return;
    if (targetNode.closest('.mac-frame')) return;

    var wrapper = document.createElement('div');
    var frameType = el.tagName === 'IMG' ? 'image' : el.tagName.toLowerCase();
    wrapper.className = 'mac-frame mac-frame-' + frameType;

    var titleText = 'file';
    if (el.tagName === 'IMG') {
      titleText = el.getAttribute('alt') || (el.src || '').split('/').pop().split('?')[0] || 'image.png';
    } else if (el.tagName === 'VIDEO') {
      titleText = el.getAttribute('title') || 'video.mp4';
    } else if (el.tagName === 'PRE') {
      titleText = el.getAttribute('data-language') || 'code.sh';
    }

    var header = document.createElement('div');
    header.className = 'mac-frame-header';
    var dots = document.createElement('div');
    dots.className = 'mac-dots';
    ['mac-red', 'mac-yellow', 'mac-green'].forEach(function(dotClass) {
      var dot = document.createElement('span');
      dot.className = 'mac-dot ' + dotClass;
      dots.appendChild(dot);
    });
    var frameTitle = document.createElement('div');
    frameTitle.className = 'mac-title';
    frameTitle.textContent = titleText;
    var spacer = document.createElement('div');
    spacer.className = 'mac-spacer';
    header.appendChild(dots);
    header.appendChild(frameTitle);
    header.appendChild(spacer);

    targetNode.parentNode.insertBefore(wrapper, targetNode);
    wrapper.appendChild(header);

    var contentDiv = document.createElement('div');
    contentDiv.className = 'mac-frame-content';
    contentDiv.appendChild(targetNode);
    wrapper.appendChild(contentDiv);
  });

  function upgradeBloggerImageUrl(url) {
    if (!url) return url;
    /* Cap display size — s0 full originals make Tutorial→post navigation feel slow. */
    return String(url)
      .replace(/\/[swh]\d{2,4}(-[a-z0-9]+)?\//gi, '/w1280/')
      .replace(/=[swh]\d{2,4}(-[a-z0-9]+)?/gi, '=w1280');
  }

  function isMobileViewport() {
    return window.matchMedia('(max-width: 860px)').matches;
  }

  function stageBudget(isLandscape) {
    var mobile = isMobileViewport();
    var parent = document.querySelector('.post-body') || document.body;
    var availW = Math.max(240, Math.min(parent.clientWidth || window.innerWidth, window.innerWidth) - 4);
    var vh = window.innerHeight || 800;
    var locked = document.documentElement.getAttribute('data-qcx-unlocked') !== '1';
    var lockedCap = Math.min(vh * 0.4, 280);
    if (isLandscape) {
      var maxW = availW;
      var maxH = mobile ? Math.min(vh * 0.42, 320) : Math.min(vh * 0.58, 560);
      if (locked) maxH = Math.min(maxH, lockedCap);
      var ratio = 16 / 9;
      var hFromW = maxW / ratio;
      if (hFromW > maxH) maxW = maxH * ratio;
      else maxH = hFromW;
      return { w: Math.round(maxW), h: Math.round(maxH), ratio: ratio };
    }
    /* Compact portrait frame sized to the image — desktop pulls it toward the
       right rail via CSS so the void between phone shot and sidebar shrinks. */
    var maxWp = mobile ? Math.min(availW * 0.92, 360) : Math.min(availW * 0.72, 400);
    var maxHp = mobile ? Math.min(vh * 0.68, 640) : Math.min(vh * 0.78, 740);
    if (locked) maxHp = Math.min(maxHp, lockedCap);
    var ratioP = 9 / 16;
    var hFromWp = maxWp / ratioP;
    if (hFromWp > maxHp) maxWp = maxHp * ratioP;
    else maxHp = hFromWp;
    return { w: Math.round(maxWp), h: Math.round(maxHp), ratio: ratioP };
  }

  function fitMacFrameImage(img) {
    if (!img || img.tagName !== 'IMG') return;
    var frame = img.closest ? img.closest('.mac-frame-image') : null;
    if (!frame) return;
    var content = frame.querySelector('.mac-frame-content');
    if (!content) return;

    var hi = upgradeBloggerImageUrl(img.getAttribute('src') || img.src || '');
    if (hi && hi !== img.getAttribute('src') && hi !== img.src) {
      img.setAttribute('src', hi);
      img.src = hi;
    }
    var link = img.closest('a');
    if (link && link.href) {
      var hiHref = upgradeBloggerImageUrl(link.href);
      if (hiHref && hiHref !== link.href) link.href = hiHref;
    }

    img.removeAttribute('width');
    img.removeAttribute('height');

    function applyFit() {
      var nw = img.naturalWidth || 0;
      var nh = img.naturalHeight || 0;
      if (nw < 2 || nh < 2) return;
      var isLandscape = nw >= nh;
      frame.classList.remove('mac-orient-landscape', 'mac-orient-portrait');
      frame.classList.add(isLandscape ? 'mac-orient-landscape' : 'mac-orient-portrait');

      var stage = stageBudget(isLandscape);
      /* CSS variables beat competing !important width/height rules. */
      frame.style.setProperty('--qcx-stage-w', stage.w + 'px');
      frame.style.setProperty('--qcx-stage-h', stage.h + 'px');
      frame.style.setProperty('--qcx-stage-ar', String(stage.ratio));
      content.style.setProperty('--qcx-stage-w', stage.w + 'px');
      content.style.setProperty('--qcx-stage-h', stage.h + 'px');
      content.style.setProperty('--qcx-stage-ar', String(stage.ratio));

      /* Fit inside stage, never upscale past native pixels. */
      var scale = Math.min(1, stage.w / nw, stage.h / nh);
      var dw = Math.max(1, Math.round(nw * scale));
      var dh = Math.max(1, Math.round(nh * scale));
      frame.style.setProperty('--qcx-img-w', dw + 'px');
      frame.style.setProperty('--qcx-img-h', dh + 'px');
      img.style.setProperty('--qcx-img-w', dw + 'px');
      img.style.setProperty('--qcx-img-h', dh + 'px');
    }

    if (img.complete && img.naturalWidth > 1) applyFit();
    else img.addEventListener('load', applyFit, { once: true });
    img.__qcxApplyFit = applyFit;
  }

  function fitAllMacFrameImages() {
    Array.prototype.forEach.call(
      document.querySelectorAll('.post-body .mac-frame-image img'),
      fitMacFrameImage
    );
  }

  var fitTimer = null;
  function scheduleFitAll() {
    if (fitTimer) clearTimeout(fitTimer);
    fitTimer = setTimeout(fitAllMacFrameImages, 80);
  }

  fitAllMacFrameImages();
  window.addEventListener('load', fitAllMacFrameImages);
  window.addEventListener('resize', scheduleFitAll);
  window.addEventListener('orientationchange', scheduleFitAll);
  if (window.visualViewport) {
    window.visualViewport.addEventListener('resize', scheduleFitAll);
  }
}
/* Boot frames early + retry so every post image gets a fixed mac-frame. */
function qcxScheduleMacFrames() {
  qcxBootMacFrames();
  window.setTimeout(qcxBootMacFrames, 60);
  window.setTimeout(qcxBootMacFrames, 400);
  window.setTimeout(qcxBootMacFrames, 1200);
}
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', qcxScheduleMacFrames, { once: true });
} else {
  qcxScheduleMacFrames();
}
window.addEventListener('load', qcxBootMacFrames, { once: true });
//
